CREATE TABLE "tiktok_backfills" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"from_time" timestamp with time zone NOT NULL,
	"until_time" timestamp with time zone NOT NULL,
	"state" text DEFAULT 'fetching' NOT NULL,
	"orders_done_until" timestamp with time zone,
	"returns_done_until" timestamp with time zone,
	"cancellations_done_until" timestamp with time zone,
	"statements_done_until" timestamp with time zone,
	"payments_done_until" timestamp with time zone,
	"orders_slice_seconds" integer DEFAULT 21600 NOT NULL,
	"requested_by_staff_user_id" uuid NOT NULL,
	"requested_at" timestamp with time zone NOT NULL,
	"fetched_at" timestamp with time zone,
	"confirmed_by_staff_user_id" uuid,
	"confirmed_at" timestamp with time zone,
	"last_run_at" timestamp with time zone,
	"last_error_code" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tiktok_backfills_state_check" CHECK ("tiktok_backfills"."state" in ('fetching', 'fetched', 'confirmed')),
	CONSTRAINT "tiktok_backfills_from_floor_check" CHECK ("tiktok_backfills"."from_time" >= '2026-11-30T17:00:00.000Z'::timestamptz),
	CONSTRAINT "tiktok_backfills_range_check" CHECK ("tiktok_backfills"."until_time" > "tiktok_backfills"."from_time"),
	CONSTRAINT "tiktok_backfills_slice_check" CHECK ("tiktok_backfills"."orders_slice_seconds" between 60 and 21600),
	CONSTRAINT "tiktok_backfills_fetched_check" CHECK (("tiktok_backfills"."state" = 'fetching') = ("tiktok_backfills"."fetched_at" is null)),
	CONSTRAINT "tiktok_backfills_confirmed_check" CHECK (("tiktok_backfills"."state" = 'confirmed') = ("tiktok_backfills"."confirmed_at" is not null and "tiktok_backfills"."confirmed_by_staff_user_id" is not null)),
	CONSTRAINT "tiktok_backfills_last_error_code_check" CHECK ("tiktok_backfills"."last_error_code" is null or char_length("tiktok_backfills"."last_error_code") <= 64)
);
